SELECT
  min(latitude) AS min_latitude,
  min(longitude) AS min_longitude,
  max(latitude) AS max_latitude,
  max(longitude) AS max_longitude,
  cast(sum(population) as integer) AS population
FROM yemen_2020
WHERE
  type='total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((42.7424955 16.4319879,42.8150271 15.9789242,42.6008808 15.7338338,43.1973836 13.6383156,43.1973593 13.2713432,43.3774048 12.7736274,44.0679825 12.5659291,45.4692762 12.9796636,45.7068655 13.2735401,46.1521258 13.3902059,46.7017494 13.3582089,47.5065438 13.6125315,47.7611187 13.8130073,47.986417 13.9696453,48.2721619 13.9208772,48.7410359 13.9987909,49.1235534 14.4276993,49.9266493 14.7582261,50.8389791 14.9671435,52.3825224 15.6122317,52.4166549 16.1987907,53.1832306 16.5006759,51.9999875 19.1257717,48.9528374 18.5361949,47.8660654 17.9267562,47.5389198 17.2658367,47.1625379 17.009943,46.7999838 17.0208497,46.8131681 17.3540642,45.8754426 17.3118169,45.2036328 17.4596701,44.1109908 17.479964,43.444879 17.3909876,43.2037046 17.5260328,43.1953295 17.0648469,43.1200082 16.7036501,42.7424955 16.4319879))')
  );
